public class SafelistTest {

    @Test
    public void none_Safelist_ReturnsNone() {
        assertSame(Safelist.none(), Safelist.none());
    }

    @Test
    public void simpleText_SimpleText_ReturnsSimpleText() {
        Safelist safelist = Safelist.simpleText();
        assertSame(safelist, Safelist.simpleText());
    }

    @Test
    public void basic_BasicReturnBasic() {
        Safelist safelist = Safelist.basic();
        assertSame(safelist, Safelist.basic());
    }

    @Test
    public void basicWithImages_BasicWithImages_ReturnsBasicWithImages() {
        Safelist safelist = Safelist.basicWithImages();
        assertSame(safelist, Safelist.basicWithImages());
    }

    @Test
    public void relaxed_RelaxedReturnRelaxed() {
        Safelist safelist = Safelist.relaxed();
        assertSame(safelist, Safelist.relaxed());
    }

    @Test
    public void copy_CopyOfSafelist_ReturnsCopyOfSafelist() {
        Safelist safelist = new Safelist(Safelist.simpleText());
        Safelist copy = safelist.copy();
        assertEquals(safelist, copy);
    }

    @Test
    public void addTags_AddTagsReturnsNewSafelistWithAddedTags() {
        Safelist safelist = Safelist.addTags("a", "b");
        assertEquals(2, safelist.getSafeTags().size());
    }

    @Test
    public void removeTags_RemoveTagsReturnsNewSafelistWithoutRemovedTags() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addTags("a", "b").removeTags("a");
        assertEquals(1, safelist.getSafeTags().size());
    }

    @Test
    public void addAttributes_AddAttributesReturnsNewSafelistWithAddedAttributes() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addAttributes("img", "alt", "example-alt");
        assertEquals(1, safelist.getEnforcedAttributes("img").size());
    }

    @Test
    public void removeAttributes_RemoveAttributesReturnsNewSafelistWithoutRemovedAttributes() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addAttributes("img", "alt", "example-alt").removeAttributes("img");
        assertEquals(0, safelist.getEnforcedAttributes("img").size());
    }

    @Test
    public void addEnforcedAttribute_AddEnforcedAttributeReturnsNewSafelistWithAddedAttribute() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addEnforcedAttribute("a", "href", "https://example.com");
        assertEquals(1, safelist.getEnforcedAttributes("a").size());
    }

    @Test
    public void removeEnforcedAttribute_RemoveEnforcedAttributeReturnsNewSafelistWithoutRemovedAttribute() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addEnforcedAttribute("a", "href", "https://example.com").removeEnforcedAttribute("a");
        assertEquals(0, safelist.getEnforcedAttributes("a").size());
    }

    @Test
    public void preserveRelativeLinks_PreserveRelativeLinksReturnsNewSafelistWithPreservedRelativeLinks() {
        Safelist safelist = new Safelist(Safelist.simpleText()).preserveRelativeLinks(false);
        assertFalse(safelist.isSafeAttribute(null, null, null));
    }

    @Test
    public void addProtocols_AddProtocolsReturnsNewSafelistWithAddedProtocols() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addProtocols("a", "href", "https://example.com");
        assertEquals(1, safelist.getEnforcedAttributes("a").size());
    }

    @Test
    public void removeProtocols_RemoveProtocolsReturnsNewSafelistWithoutRemovedProtocols() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addProtocols("img", "alt", "example-alt").removeProtocols("img");
        assertEquals(0, safelist.getEnforcedAttributes("img").size());
    }

    @Test
    public void isSafeTag_IsSafeTagReturnsTrueForSimpleTags() {
        assertTrue(Safelist.simpleText().isSafeTag("p"));
    }

    @Test
    public void isSafeAttribute_IsSafeAttributeReturnsTrueForImagesWithAlt() {
        Safelist safelist = new Safelist(Safelist.simpleText()).addAttributes("img", "alt", "example-alt");
        assertTrue(safelist.isSafeAttribute(null, null, new Attribute("alt", "example-alt")));
    }

